'use strict';
// 构建私有候选：new.md 追加 old 的离线恢复段（逐字）；catalog.md 仅 old.md 引用改 new.md。
const fs = require('fs');
const path = require('path');

const repo = '/private/var/folders/0v/f_smd31500113ppkqs66c9yr0000gn/T/skill-up-914807377';
const scratch = process.argv[2];

const oldB = fs.readFileSync(path.join(repo, 'docs/solutions/old.md'));
const newB = fs.readFileSync(path.join(repo, 'docs/solutions/new.md'));
const catB = fs.readFileSync(path.join(repo, 'docs/solutions/catalog.md'));

// 1) old.md 离线恢复段 = 从 "## 离线恢复" 起到文件末尾（末尾单个 \n）
const marker = Buffer.from('## 离线恢复', 'utf8');
const idx = oldB.indexOf(marker);
if (idx < 0) throw new Error('old.md 未找到离线恢复标题');
const oldSection = oldB.subarray(idx);
const expected = Buffer.from('## 离线恢复\n\n离线时保留最后可用凭据，不删除备份。\n', 'utf8');
if (!oldSection.equals(expected)) {
  throw new Error('old 段落与预期逐字不符: ' + JSON.stringify(oldSection.toString('utf8')));
}

// 2) new.md 现状断言：以 "复验认证。\n" 结尾且仅一个换行
const newTail = Buffer.from('认证失败时刷新凭据，更新后复验认证。\n', 'utf8');
if (!newB.subarray(newB.length - newTail.length).equals(newTail)) {
  throw new Error('new.md 结尾与预期不符: ' + JSON.stringify(newB.subarray(newB.length - 40).toString('utf8')));
}

// 3) new 候选 = 原字节 + 一个空行 + old 的离线恢复段（逐字，含末尾换行）
const suffix = Buffer.concat([Buffer.from('\n', 'utf8'), oldSection]);
const newCand = Buffer.concat([newB, suffix]);
fs.writeFileSync(path.join(scratch, 'new.md.candidate'), newCand);

// 4) catalog 候选：仅将 old.md#离线恢复 改为 new.md#离线恢复，其余字节不变
const before = 'old.md#离线恢复';
const after = 'new.md#离线恢复';
const catS = catB.toString('utf8');
const hits = catS.split(before).length - 1;
const oldRefs = (catS.match(/old\.md/g) || []).length;
if (hits !== 1 || oldRefs !== 1) throw new Error('catalog 引用计数异常 hits=' + hits + ' oldRefs=' + oldRefs);
const catCand = Buffer.from(catS.replace(before, after), 'utf8');
fs.writeFileSync(path.join(scratch, 'catalog.md.candidate'), catCand);

console.log('old 段逐字校验: 通过');
console.log('new.md 原始字节:', newB.length, '-> 候选字节:', newCand.length);
console.log('catalog.md 原始字节:', catB.length, '-> 候选字节:', catCand.length);

